Ext._define('rh.queryregistration.ConsultationGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.queryregistration.ConsultationWindow',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 30, renderer: core.rendererIconGrid},
                    {header: 'Id', dataIndex: 'pk', width: 50,},
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: 'Título do Relatório', dataIndex: 'title', width: 1150},
                    {header: 'Consulta SQL', dataIndex: 'sql', width: 90, hidden: true}
                ]
            );

        return this._columnModel;
    },


    defaultClickFunction: function() {
        if(this.getSelectionModel().getSelected()) this.getFormTags();
    },


    getFormTags:function(){
        params = this.getSelectionModel().getSelected()
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(
                'QRConsultation',
                'get_tags'
            ),
            params: {
                pk:params.id,
            },
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                if(obj.success)
                   this.OpenTagWindow(obj.tags,obj.multichoices,params.id)
                else
                    Ext.Msg.show({
                        title: 'parâmetros',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: obj.message
                    });
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },


    OpenTagWindow:function(fields,multichoices,pk){
        Ext._create('rh.queryregistration.TagsWindow', {
            title: 'Parâmetros',
            scope: this,
            data:fields,
            multichoices:multichoices,
            pk: pk,
            closable: true,
        }).show();
    },

});

core.RestfulGrid.register(
    'rh.queryregistration.ConsultationRestful',
    'rh.queryregistration.ConsultationGrid'
);

